INSERT INTO `wp_3_posts` VALUES (2,1,'2012-12-20 08:51:03','2012-12-20 08:51:03','Aquest és un exemple de pàgina. És diferent a un article perquè romandrà en un lloc i es mostrarà en la navegació del bloc (en la majoria d\'aparences). Molta gent comença amb una pàgina \"Quant a\" que els presenta als visitants potencials del bloc. Es podria dir quelcom així: \n<blockquote>Hola a tothom! Treballo de missatger de dia, sóc aspirant a actor de nit, i aquest és el meu bloc. Visc a Barcelona, tinc un gosa meravellosa que es diu Lluna, i m\'agraden les calçotades. (I quedar atrapat per la pluja.)</blockquote>\n\n... o quelcom així:\n\n<blockquote>La Companyia d\'Adobs XYZ es va fundar el 1971, i ha estat proporcionant adobs de qualitat des de llavors. Situada en Gotham City, XYZ dóna feina a més de 2,000 persones i fa tot tipus de meravelloses tasques per a la comunitat de Gotham.</blockquote>\n \n\n \nCom a usuari nou del WordPress, heu d\'anar al <a href=\"https://blocs-aws.xtec.cat/elsdofins/wp-admin/\">tauler</a> a esborrar aquesta pàgina i crear pàgines noves amb el vostre contingut. Que es diverteixin!','Pàgina d\'exemple','','publish','open','open','','pagina-exemple','','','2012-12-20 08:51:03','2012-12-20 08:51:03','',0,'https://blocs-aws.xtec.cat/elsdofins/?page_id=2',0,'page','',0),(42,1,'2015-02-23 09:15:47','0000-00-00 00:00:00','','Home','','draft','open','open','','','','','2015-02-23 09:15:47','0000-00-00 00:00:00','',0,'https://blocs-aws.xtec.cat/elsdofins/?p=42',1,'nav_menu_item','',0),(43,1,'2015-02-23 09:15:47','0000-00-00 00:00:00','','Pàgina d\'exemple','','draft','open','open','','','','','2015-02-23 09:15:47','0000-00-00 00:00:00','',0,'https://blocs-aws.xtec.cat/elsdofins/?p=43',1,'nav_menu_item','',0),(44,1,'2015-02-23 09:15:47','0000-00-00 00:00:00','','Pàgina d\'exemple','','draft','open','open','','','','','2015-02-23 09:15:47','0000-00-00 00:00:00','',0,'https://blocs-aws.xtec.cat/elsdofins/?p=44',1,'nav_menu_item','',0),(45,1,'2015-02-23 09:1